```sql
CREATE TABLE ingredient (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  category INTEGER NOT NULL,
  Einheitssymbol TEXT NOT NULL,

  CHECK(category IN (SELECT id FROM category)),
