);

CREATE TABLE omlette_recipe (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ingredient INTEGER NOT NULL,
  amount REAL NOT NULL,

  CHECK(amount > 0),

  FOREIGN KEY (ingredient) REFERENCES ingredient(id)
);
```

