        Assertions.assertThat(invoiceCreated.getInvoiceNumber()).isEqualTo(dataGenerator.getInvoiceNumber());
        Assertions.assertThat(invoiceCreated.getCustomerName()).isEqualTo(dataGenerator.getCustomerName());
        Assertions.assertThat(invoiceCreated.getAmount()).isEqualTo(dataGenerator.getAmount());
    }

    public static void assertInvoiceReadWithData(DatafakerData invoiceRead, DataGenerator dataGenerator) {
        Assertions.assertThat(invoiceRead.getInvoiceNumber()).isEqualTo(dataGenerator.getInvoiceNumber());
