        Assertions.assertThat(invoiceRead.getAmount()).isEqualTo(dataGenerator.getAmount());
    }

    public static void assertInvoiceUpdatedWithData(DatafakerData invoiceUpdated, DataGenerator dataGenerator) {
        Assertions.assertThat(invoiceUpdated.getInvoiceNumber()).isEqualTo(dataGenerator.getInvoiceNumber());
        Assertions.assertThat(invoiceUpdated.getCustomerName()).isEqualTo(dataGenerator.getCustomerName());
        Assertions.assertThat(invoiceUpdated.getAmount()).isEqualTo(dataGenerator.getAmount());
    }

    public static void assertInvoiceDeleted(String invoiceNumber, DatafakerData data) {
        Assertions.assertThatThrownBy(() -> {
            Assertions.assertThat(data.getInvoiceNumber()).isEqualTo(invoiceNumber);
        }).isInstanceOf(AssertionFailure.class);
    }
}

