            ArrayList<String> list = new ArrayList<>();
            list.add(flower);
            categories.put(key, list);
        }
    }
    System.out.println(categories);

    // Verwendung von Enum
    enum FlowerType {
        LILAC("Lilac"),
        DAISY("Daisy"),
        MARIGOLD("Marigold"),
        CHRYSANTHEMUM("Chrysanthemum");

