   // create the categories hashmap once
   String[] categoryKeys = {"Lilac", "Daisy", "Marigold", "Chrysanthemum"};
   for (String key : categoryKeys) {
       categories.put(key, new ArrayList<>());
   }

   for (String flower : flowers) {
       String key = "";
