import java.util.*;

public class FlowerCategoriesOptimized {

    private static String getGenericFlowerCategoryName(String str) {
        // Beginn der benutzerdefinierten Kategorisierung
        String category;
        if (str.toUpperCase().startsWith("LI") || str.toUpperCase().startsWith("LIL")) {
            category = "LILAC";
        } else if (str.toUpperCase().startsWith("DA")) {
            category = "DAISY";
        } else if (str.toUpperCase().startsWith("MA") || str.toUpperCase().startsWith("MAR")) {
            category = "MARIHGOLD";
        } else if (str.toUpperCase().startsWith("CH") || str.toUpperCase().startsWith("CHR")) {
            category = "CHRYSANTHEMUM";
        } else {
