        string userInput = Console.ReadLine().ToLower(); // alles in Kleinbuchstaben einlesen

        var Gefühle = new Dictionary<string, string>()
        {
            {"schadenfreude", "Schadenfreude"},
            {"misophonia", "Misophonie"},
            {"ennui", "Ennui"},
            {"ennervation", "Ennervation"},
            {"dejection", "Missmut"},
            {"verdrossenheit", "Verdruss (deutsch)"},
            {"weltschmerz", "Weltschmerz"},
            {"todesängste", "Todesschrecken (deutsch)"}, // andere Gefühlsannahmen hinzufügen
            {"malaise", "Ungeklärtes Unwohlsein oder Unbehagen"}
        };

        if (Gefühle.ContainsKey(userInput))
        {
            Console.WriteLine($"Das Gefühl, an das Sie denken, kann als '{Gefühle[userInput']}' beschrieben werden.");
        }
