3. Erstellung einer neuen Regel in einer Datei mit dem Namen `my-vue-no-modify-internal-state.js` im Ordner `plugins/my-vue`, die wie folgt aussehen sollte:

```javascript
const Vue = require('vue/types/vue');
const { createRuleChecker } = require('eslint');

const checker = createRuleChecker({
  name: 'my-vue-no-modify-internal-state',
  defaultOptions: [
    {
      excludeMethodsThatUpdatePropsOrData: false,
      detectNestedFunctionCalls: false
    }
  ]
});

function createRule(options) {
  function rule(context) {
    const { node } = context;

    const { detectNestedFunctionCalls, excludeMethodsThatUpdatePropsOrData } = options;

    function isLifecycleHookMethod(node) {
      const { type } = node;

      return (
        type === 'MethodDefinition' &&
        (type === 'CompositionFunction' || type === 'ArrowFunctionExpression') &&
        (node.key.name === 'created' ||
          node.key.name === 'activated' ||
          node.key.name === 'deactivated' ||
          node.key.name === 'beforeCreate' ||
          node.key.name === 'beforeMount' ||
          node.key.name === 'beforeUpdate' ||
          node.key.name === 'beforeDestroy' ||
          node.key.name === 'beforeActivate' ||
          node.key.name === 'beforeDeactivate' ||
          node.key.name === 'activated' ||
          node.key.name === 'deactivated' ||
          node.key.name === 'mounted' ||
          node.key.name === 'updated' ||
          node.key.name === 'rendered' ||
          node.key.name === 'destroyed')
      );
    }

    function checkNode(context) {
      const { node } = context;

      if (
        isLifecycleHookMethod(node) &&
        (!excludeMethodsThatUpdatePropsOrData || !isMethodUpdatingPropsOrData(node))
      ) {
        const { method } = node;

        if (
          detectNestedFunctionCalls &&
          isNestedFunctionCall(method)
        ) {
          context.report({
            node,
            message: 'Lifecycle hook method cannot modify internal component state when called from a nested function.'
          });
        } else {
          context.report({
            node,
            message:
              'Lifecycle hook method cannot modify internal component state directly. Consider moving any modifications to the next tick.'
          });
        }
      }
    }

    function isMethodUpdatingPropsOrData(node) {
      const { body } = node;
      const { body: parentBody } = context.getAncestor(node, (n) => Vue.types.componentMethods().includes(n.type));

      if (!parentBody) {
        return false;
      }

      const propsToUpdate = Object.keys(node.value.arguments.nodes[0].properties)
        .filter((propertyName) => Vue.types.objectProperty().includes(node.value.arguments.nodes[0].properties[propertyName]));

      const dataToUpdate = Object.keys(method.value)
        .filter((propertyName) => Vue.types.objectProperty().includes(method.value[propertyName]));

      return propsToUpdate.length || dataToUpdate.length || hasNestedMethodCallUpdatingPropsOrData(node, parentBody);
    }

    function hasNestedMethodCallUpdatingPropsOrData(node, parentBody) {
      return parentBody.body.some((stmt) => {
        if (Vue.types.CallExpression().includes(stmt.type)) {
          const args = stmt.arguments;

          return args.length === 1 &&
            Vue.types.ObjectPattern().includes(stmt.arguments[0].type) &&
            hasNestedMethodCallUpdatingPropsOrData(args[0], parentBody);
        } else if (Vue.types.MethodDefinition().includes(stmt.type)) {
          const { key: methodName } = stmt;

          if (methodName.value === 'watch' && Vue.types.ObjectPattern().includes(stmt.value.arguments.nodes[0].type)) {
            return hasNestedMethodCallUpdatingPropsOrData(stmt.value.arguments.nodes[0], parentBody);
          } else {
            return false;
          }
        } else {
          return false;
        }
      });
    }

    function isNestedFunctionCall(node) {
      return Vue.types.FunctionExpression().includes(node.type) || Vue.types.AwaitExpression().includes(node.type);
    }

    return {
      MethodDefinition(node) {
        checkNode({ context, node });
      }
    };
  }

  return rule;
}

checker.createRule(defaultOptions, createRule);

module.exports = checker;
