function noChangingInternalState(context) {
  return {
    CallExpression(node) {
      // Nur Lifecycle Hook Aufrufe des Internen Components prüfen
      const { callee, arguments: args } = node;
      if (!isLifecycleHook(callee) || NO_CHANGE_STATE_METHOD_NAMES.includes(callee.name)) {
        return;
      }

      // Alle Zielpfade für this oder props überprüfen und Warnungen ausgeben
      const referencedProperties = getOnlyOwnProperties(node);
      referencedProperties.forEach((prop) => {
        const isTargetingThis = prop.type === 'MemberExpression' && prop.object.type === 'ThisExpression';
        const isTargetingProps = prop.type === 'MemberExpression' && prop.object.type === 'Identifier' && prop.object.name === 'props';

        if (isTargetingThis || isTargetingProps) {
          // Komponentenstatus würde durch diesen Aufruf geändert werden
          const methodName = PropositionalizeMethod(node.callee);
          if (COMBINED_WOULD_CHANGE_STATE_METHOD_NAMES.includes(methodName)) {
            context.report({
              node,
              message: `Aktualisiere lifecycle hook "${methodName}" darf nicht den internen Komponentenstatus verändern`,
            });
          }

          // Anderen Lifecycle Hook Methoden aufrufen, die den internen Komponentenstatus verändern
          const callerProperties = getOnlyOwnProperties(node.arguments[0]);
          callerProperties.forEach((prop) => {
            const methodName = PropositionalizeMethod(prop.object || prop);
            if (COMBINED_WOULD_CHANGE_STATE_METHOD_NAMES.includes(methodName)) {
