      'CallExpression'(node) {
        // Nur Methodenaufrufe überprüfen
        if (!node.callee.object || !node.callee.property) {
          return;
        }

        const callee = node.callee.property.name;

        if (!['beforeCreate', 'created', 'beforeMount', 'mounted', 'beforeUpdate', 'updated', 'activated', 'deactivated', 'beforeDestroy', 'destroyed'].includes(node.parent.type) ||
            !['mount', 'update', 'activate', 'deactivate', 'destroy'].includes(callee)) {
          return;
        }

        const methodName = node.parent.parent.key.name;
        const isHookMethod = methodName.startsWith('before') || methodName.startsWith('activatedError') || methodName.startsWith('deactivatedError');

        if (isHookMethod && internalStatusModifiers.includes(node.callee.name)) {
          context.report({
            node,
            message: `Don't modify internal component status within ${methodName} (${callee}).`,
            fix(fixer) {
              // Keine Änderungen für dieses Problem beheben
              return null;
            },
          });
        }

        // Eventuell wird eine weitere Methode aufgerufen, die internen Status ändert,
        // daher überprüfen wir, ob der Aufruf eine weitere Methodenreferenz enthält
        if (node.arguments && node.arguments.length > 0) {
          const args = node.arguments.map((arg) => {
            return inspect(arg, { noKeywords: true });
          });
          const callExpr = `${callee}(${args.join(',')})`;

          const calleeNode = node.callee.object || node.callee;
          const calleeName = calleeNode.type === 'Identifier' ? calleeNode.name : null; // Wenn ein Member-Expression verwendet wird

          if (internalStatusModifiers.includes(calleeName)) {
            context.report({
              node,
              message: `Avoid calling function "${callee}" within ${methodName}, which modifies internal component status (${callExpr}).`,
              fix(fixer) {
                // Keine Änderungen für dieses Problem beheben
                return null;
              },
            });
          }
        }
      },
    };
  },
};

// Variablen für die internen Status-Änderungsmethoden definieren
const internalStatusModifiers = [
  'push', 'splice', 'shift', 'pop', 'unshift', 'sort', 'reverse', 'filter', 'forEach', 'map', 'some', 'every', 'findIndex', 'indexOf', 'lastIndexOf'
];

export default rule;
```

